function validate([number, digit]) {
  if (typeof number !== 'string' || number.length < 2 || number.length > 100) return 'number needs 2 to 100 digits.';
  if (!/^[1-9]+$/.test(number)) return 'number may contain only the digits 1 to 9.';
  if (typeof digit !== 'string' || !/^[1-9]$/.test(digit)) return 'digit must be one character from 1 to 9.';
  if (!number.includes(digit)) return 'digit must appear in number.';
  return null;
}

