function removeDigit(number, digit) {
  let best = null;
  for (let i = 0; i < number.length; i++) {
    if (number[i] !== digit) continue;
    const candidate = number.substring(0, i) + number.substring(i + 1);
    if (best === null || BigInt(candidate) > BigInt(best)) best = candidate;
  }
  return best;
}

