function generate(rand, size) {
  const pick = (text) => text[Math.floor(rand() * text.length)];
  const alphabet = size === 'large' ? (rand() < 0.5 ? '123456789' : '456') : (rand() < 0.5 ? '123' : '123456789');
  const length = size === 'large' ? 100 : 2 + Math.floor(rand() * 7);
  let number = '';
  for (let i = 0; i < length; i++) number += pick(alphabet);
  return [number, pick(number)];
}
